UNOFFICIAL_RU = {190: "ч.1 изменена ЗРУ-1095 от 11.11.2025", 262: "ч.1 изменена ЗРУ-1095 от 11.11.2025", 173: "изменены только основания выплаты (абз.2 ч.2, ЗРУ-1070 от 23.06.2025), размеры пособия не менялись"}
def note(art, q=""):
    if art == 218 and "государственной власти" in q:
        return "Ч.2 ст.218 изменена ЗРУ-1109 от 30.12.2025; русский текст на lex.uz неофициальный перевод, сверить с официальным узбекским текстом."
    if art in UNOFFICIAL_RU:
        return f"Статья менялась ({UNOFFICIAL_RU[art]}); русский текст на lex.uz неофициальный перевод, сверить с официальным узбекским текстом. Модели с устаревшими данными могут ответить по старой редакции."
    return None

def main():
    rows = []
    i = 0
    for (art, topic, qr, qe, ar, ae, kf, quote) in FACT:
        i += 1
        rows.append(dict(id=f"F{i:03d}", note=note(art, qr), type="fact", topic=topic, article=art, question_ru=qr, question_en=qe,
                         answer_ru=ar, answer_en=ae, key_facts=kf, quote=quote, source=URL))
    for k, (art, topic, qr, qe, ar, ae, kf, quote) in enumerate(FALSE_PREMISE, 1):
        rows.append(dict(id=f"P{k:03d}", note=note(art, qr), type="false_premise", topic=topic, article=art, question_ru=qr, question_en=qe,
                         answer_ru=ar, answer_en=ae, key_facts=kf, quote=quote, source=URL))
    for k, (art, qr, qe) in enumerate(NONEXIST, 1):
        rows.append(dict(id=f"N{k:03d}", type="nonexistent_article", topic="abstain", article=art, question_ru=qr, question_en=qe,
                         answer_ru="Такой статьи нет: Трудовой кодекс Республики Узбекистан (ред. на lex.uz) содержит 593 статьи. Хороший ответ признает это и не выдумывает содержание.",
                         answer_en="No such article: the Labor Code of Uzbekistan (lex.uz version) has 593 articles. A good answer says so and does not invent content.",
                         key_facts=["нет такой статьи"], quote=None, source=URL))
    from uz_questions import UZ
    from uz_translit import lat2cyr
    for r in rows:
        r["question_uz_latn"] = UZ[r["id"]]
        r["question_uz_cyrl"] = lat2cyr(UZ[r["id"]])
    with open("data/questions_v1.jsonl", "w", encoding="utf-8") as f:
        for r in rows:
            f.write(json.dumps(r, ensure_ascii=False) + "\n")
    print(len(FACT), len(FALSE_PREMISE), len(NONEXIST), len(rows))

if __name__ == "__main__":
    main()
